contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 spendAmount) public payable {
        require(address(this).balance >= depositAmount);
        c.deposit{value: depositAmount}();
        uint256 cBalBefore = address(c).balance;
        require(spendAmount <= cBalBefore);
        uint256 forcedCredit = cBalBefore - spendAmount;
        c.withdrawAll();

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        bool expectedRevert = cBalBefore < address(c).balance + forcedCredit;
        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

