contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint drainAmount) public payable {
        require(address(this).balance >= depositAmount + drainAmount);

        c.deposit{value: depositAmount}();

        uint balBefore = address(c).balance;
        uint creditBefore = c.credit(address(this));

        // Drain C's Ether by making the test contract call deposit from the same caller,
        // then withdraw the newly created credit, leaving C's balance possibly short
        // relative to the remaining credit.  However, the test contract is the caller
        // of every c call; to create a state where credit > address(c).balance we
        // deposit, then directly reduce C's balance is not possible via the public API
        // except by withdrawing (which also reduces credit).  So instead we check the
        // invariant around the withdrawal call itself: the call reverts exactly when
        // creditBefore > balBefore.

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        uint balAfter = address(c).balance;
        uint creditAfter = c.credit(address(this));

        assert(
            (creditBefore > balBefore)
                ? (reverted && balAfter == balBefore && creditAfter == creditBefore)
                : (!reverted && balAfter == balBefore - creditBefore && creditAfter == 0)
        );
    }

    receive() external payable {}
}

